  if (!policies || typeof policies !== "object") {
    throw new Error("升级资源[" + packageName + "]缺少 ResourcePolicies.ApiEngines");
  }
  var seen = {};
  for (var index = 0; index < engines.length; index++) {
    var engine = engines[index] || {};
