            var currentValues = parseMenuPermissionArray(roleLimit.Permission);
            var currentSeen = {};
            for (var currentIndex = 0; currentIndex < currentValues.length; currentIndex++) {
                appendUniqueMenuPermission([], currentSeen, currentValues[currentIndex]);
